/**
 * The patient app's service worker (FRONTEND.md §9: "PWA — app shell
 * precache, runtime caching, install prompt").
 *
 * Hand-written rather than generated by Workbox, and deliberately small. What
 * this app needs from a service worker is narrow and the rules are strict
 * enough that a generated config would be harder to reason about than forty
 * lines that say exactly what they do.
 *
 * ## The one rule that matters
 *
 * **A queue is never served from a cache.** `FR-OFF-03` and `PRD.md` §3.2: a
 * live number must say how old it is, and a serial answered from a cache is a
 * number with no age at all. So every `/api/` request goes to the network and
 * fails honestly if there is none — the screens already have an offline state
 * that says the figures have stopped arriving (`FR-PAT-36`), and that is a
 * better answer than a stale serial presented as current.
 *
 * What is cached is the shell: the HTML, the JS, the CSS, the font. That is
 * what makes the app open instantly on a bad connection and show its offline
 * state, rather than showing the browser's dinosaur.
 */

const SHELL = 'shell-v1';

/**
 * Paths worth having before they are asked for.
 *
 * Deliberately short. Next fingerprints its own assets and they are picked up
 * by the runtime cache below on first visit; precaching a build manifest here
 * would be a second copy of it to keep in step.
 */
const PRECACHE = ['/', '/manifest.webmanifest', '/icon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      .then(async (cache) => {
        // Individually, so one 404 does not abandon the whole install.
        await Promise.all(PRECACHE.map((path) => cache.add(path).catch(() => undefined)));
      })
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then(async (keys) => {
        await Promise.all(keys.filter((key) => key !== SHELL).map((key) => caches.delete(key)));
      })
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // Never cache the API, and never answer it from one. A queue read from a
  // cache is a number with no age, which is the one thing this product does
  // not do (`FR-OFF-03`, `PRD.md` §3.2).
  if (url.pathname.startsWith('/api/')) return;

  // Nor anything on another origin: the API and the socket live there.
  if (url.origin !== self.location.origin) return;

  // Never the socket.
  if (url.pathname.startsWith('/socket.io/')) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(SHELL);

      // Network first, so a deploy is picked up rather than pinned. The cache
      // is the fallback for a corridor with no signal, not the source.
      try {
        const response = await fetch(request);
        if (response.ok && response.type === 'basic') {
          void cache.put(request, response.clone());
        }
        return response;
      } catch (error) {
        const cached = await cache.match(request);
        if (cached !== undefined) return cached;

        // A navigation with nothing cached for it still gets the shell, so
        // the app opens and shows its own offline state rather than the
        // browser's error page.
        if (request.mode === 'navigate') {
          const shell = await cache.match('/');
          if (shell !== undefined) return shell;
        }

        throw error;
      }
    })(),
  );
});
